INSERT INTO word_lists (id, name, description, language, target_lang, is_public, created_by)
INSERT INTO words (list_id, word, pronunciation, definition, example, example_translation, pos, difficulty, sort_order) VALUES
('a0000000-0000-0000-0000-000000000001', 'abandon', '/əˈbændən/', '放弃；遗弃', 'He abandoned his old car and bought a new one.', '他放弃了旧车买了一辆新的。', 'v.', 1, 1),
('a0000000-0000-0000-0000-000000000001', 'abstract', '/ˈæbstrækt/', '抽象的；摘要', 'The concept is too abstract for children to understand.', '这个概念太抽象了，孩子无法理解。', 'adj.', 1, 2),
('a0000000-0000-0000-0000-000000000001', 'accurate', '/ˈækjərət/', '精确的；准确的', 'The weather forecast was not very accurate.', '天气预报不太准确。', 'adj.', 0, 3),
('a0000000-0000-0000-0000-000000000001', 'achieve', '/əˈtʃiːv/', '实现；达到', 'She achieved her goal of becoming a doctor.', '她实现了成为医生的目标。', 'v.', 0, 4),
('a0000000-0000-0000-0000-000000000001', 'acknowledge', '/əkˈnɒlɪdʒ/', '承认；确认', 'He acknowledged that he had made a mistake.', '他承认自己犯了错误。', 'v.', 1, 5),
('a0000000-0000-0000-0000-000000000001', 'adequate', '/ˈædɪkwət/', '足够的；适当的', 'The food supply is adequate for the winter.', '食物供应足够度过冬天。', 'adj.', 1, 6),
('a0000000-0000-0000-0000-000000000001', 'approach', '/əˈprəʊtʃ/', '接近；方法', 'We need a new approach to this problem.', '我们需要用新方法解决这个问题。', 'n./v.', 0, 7),
('a0000000-0000-0000-0000-000000000001', 'appropriate', '/əˈprəʊpriət/', '适当的；恰当的', 'Is this dress appropriate for the occasion?', '这件衣服适合这个场合吗？', 'adj.', 0, 8),
('a0000000-0000-0000-0000-000000000001', 'approximately', '/əˈprɒksɪmətli/', '大约；近似地', 'The journey takes approximately three hours.', '旅程大约需要三个小时。', 'adv.', 0, 9),
('a0000000-0000-0000-0000-000000000001', 'attitude', '/ˈætɪtjuːd/', '态度；看法', 'Her attitude toward work is very positive.', '她对工作的态度非常积极。', 'n.', 0, 10),
('a0000000-0000-0000-0000-000000000001', 'benefit', '/ˈbenɪfɪt/', '好处；利益', 'Regular exercise has many health benefits.', '经常锻炼有很多健康益处。', 'n.', 0, 11),
('a0000000-0000-0000-0000-000000000001', 'capable', '/ˈkeɪpəbl/', '有能力的；能干的', 'She is capable of handling this project alone.', '她有能力独自处理这个项目。', 'adj.', 0, 12),
('a0000000-0000-0000-0000-000000000001', 'characteristic', '/ˌkærəktəˈrɪstɪk/', '特征；特点', 'Patience is a characteristic of good teachers.', '耐心是好老师的特征。', 'n.', 1, 13),
('a0000000-0000-0000-0000-000000000001', 'circumstance', '/ˈsɜːkəmstəns/', '情况；环境', 'Under no circumstance should you give up.', '在任何情况下你都不应该放弃。', 'n.', 1, 14),
('a0000000-0000-0000-0000-000000000001', 'consequence', '/ˈkɒnsɪkwəns/', '结果；后果', 'You must accept the consequences of your actions.', '你必须接受你行为的后果。', 'n.', 1, 15),
('a0000000-0000-0000-0000-000000000001', 'consider', '/kənˈsɪdə/', '考虑；认为', 'Please consider all options before making a decision.', '请在做决定前考虑所有选项。', 'v.', 0, 16),
('a0000000-0000-0000-0000-000000000001', 'contribute', '/kənˈtrɪbjuːt/', '贡献；捐献', 'Everyone should contribute to the community.', '每个人都应该为社区做出贡献。', 'v.', 0, 17),
('a0000000-0000-0000-0000-000000000001', 'crucial', '/ˈkruːʃəl/', '关键的；决定性的', 'This meeting is crucial for our project.', '这次会议对我们的项目至关重要。', 'adj.', 1, 18),
('a0000000-0000-0000-0000-000000000001', 'demonstrate', '/ˈdemənstreɪt/', '证明；演示', 'The experiment demonstrated the theory was correct.', '实验证明了这个理论是正确的。', 'v.', 1, 19),
('a0000000-0000-0000-0000-000000000001', 'determine', '/dɪˈtɜːmɪn/', '决定；确定', 'We need to determine the cause of the problem.', '我们需要确定问题的原因。', 'v.', 0, 20),
('a0000000-0000-0000-0000-000000000001', 'distinguish', '/dɪˈstɪŋgwɪʃ/', '区分；辨别', 'Can you distinguish between the two species?', '你能区分这两个物种吗？', 'v.', 1, 21),
('a0000000-0000-0000-0000-000000000001', 'effective', '/ɪˈfektɪv/', '有效的；生效的', 'This medicine is very effective against colds.', '这种药对感冒非常有效。', 'adj.', 0, 22),
('a0000000-0000-0000-0000-000000000001', 'eliminate', '/ɪˈlɪmɪneɪt/', '消除；淘汰', 'We must eliminate all sources of pollution.', '我们必须消除所有污染源。', 'v.', 1, 23),
('a0000000-0000-0000-0000-000000000001', 'emerge', '/ɪˈmɜːdʒ/', '出现；浮现', 'New technologies emerge every year.', '新技术每年都会出现。', 'v.', 1, 24),
('a0000000-0000-0000-0000-000000000001', 'emphasis', '/ˈemfəsɪs/', '强调；重点', 'The teacher put emphasis on grammar.', '老师强调了语法的重要性。', 'n.', 1, 25),
('a0000000-0000-0000-0000-000000000001', 'establish', '/ɪˈstæblɪʃ/', '建立；设立', 'The company was established in 1990.', '这家公司成立于1990年。', 'v.', 0, 26),
('a0000000-0000-0000-0000-000000000001', 'evident', '/ˈevɪdənt/', '明显的；明白的', 'It is evident that he has been working hard.', '很明显他一直在努力工作。', 'adj.', 0, 27),
('a0000000-0000-0000-0000-000000000001', 'fundamental', '/ˌfʌndəˈmentəl/', '基本的；根本的', 'Freedom is a fundamental human right.', '自由是一项基本人权。', 'adj.', 1, 28),
('a0000000-0000-0000-0000-000000000001', 'generate', '/ˈdʒenəreɪt/', '产生；生成', 'Solar panels generate electricity from sunlight.', '太阳能板从阳光中产生电力。', 'v.', 0, 29),
('a0000000-0000-0000-0000-000000000001', 'guarantee', '/ˌgærənˈtiː/', '保证；担保', 'We guarantee the quality of our products.', '我们保证产品质量。', 'v./n.', 0, 30),
('a0000000-0000-0000-0000-000000000001', 'identify', '/aɪˈdentɪfaɪ/', '识别；确认', 'Can you identify the suspect in this photo?', '你能认出照片中的嫌疑人吗？', 'v.', 0, 31),
('a0000000-0000-0000-0000-000000000001', 'indicate', '/ˈɪndɪkeɪt/', '表明；指示', 'Research indicates that exercise improves mood.', '研究表明运动能改善心情。', 'v.', 0, 32),
('a0000000-0000-0000-0000-000000000001', 'interpret', '/ɪnˈtɜːprɪt/', '解释；口译', 'How do you interpret this poem?', '你怎么解释这首诗？', 'v.', 1, 33),
('a0000000-0000-0000-0000-000000000001', 'investigate', '/ɪnˈvestɪgeɪt/', '调查；研究', 'Police are investigating the crime.', '警方正在调查这起犯罪。', 'v.', 0, 34),
('a0000000-0000-0000-0000-000000000001', 'justify', '/ˈdʒʌstɪfaɪ/', '证明…正当；为…辩护', 'How can you justify such behavior?', '你怎么能为这种行为辩护？', 'v.', 1, 35),
('a0000000-0000-0000-0000-000000000001', 'maintain', '/meɪnˈteɪn/', '维持；保持', 'It is important to maintain a healthy lifestyle.', '保持健康的生活方式很重要。', 'v.', 0, 36),
('a0000000-0000-0000-0000-000000000001', 'neglect', '/nɪˈglekt/', '忽视；疏忽', 'Don''t neglect your health while working hard.', '努力工作时不要忽视健康。', 'v.', 1, 37),
('a0000000-0000-0000-0000-000000000001', 'obvious', '/ˈɒbvɪəs/', '明显的；显而易见的', 'The answer is obvious to everyone.', '答案对每个人来说都是显而易见的。', 'adj.', 0, 38),
('a0000000-0000-0000-0000-000000000001', 'participate', '/pɑːˈtɪsɪpeɪt/', '参与；参加', 'Everyone should participate in the discussion.', '每个人都应该参与讨论。', 'v.', 0, 39),
('a0000000-0000-0000-0000-000000000001', 'perceive', '/pəˈsiːv/', '感知；理解', 'She perceived a change in his behavior.', '她察觉到他行为的变化。', 'v.', 1, 40),
('a0000000-0000-0000-0000-000000000001', 'potential', '/pəˈtenʃəl/', '潜在的；潜力', 'The region has great economic potential.', '该地区有巨大的经济潜力。', 'adj./n.', 1, 41),
('a0000000-0000-0000-0000-000000000001', 'previous', '/ˈpriːviəs/', '以前的；先前的', 'She had no previous experience in this field.', '她以前在这个领域没有经验。', 'adj.', 0, 42),
('a0000000-0000-0000-0000-000000000001', 'proportion', '/prəˈpɔːʃən/', '比例；部分', 'A large proportion of students passed the exam.', '很大比例的学生通过了考试。', 'n.', 1, 43),
('a0000000-0000-0000-0000-000000000001', 'relevant', '/ˈrelɪvənt/', '相关的；有关的', 'Please include only relevant information.', '请只包含相关信息。', 'adj.', 0, 44),
('a0000000-0000-0000-0000-000000000001', 'significant', '/sɪgˈnɪfɪkənt/', '重要的；显著的', 'There has been a significant improvement in quality.', '质量有了显著提升。', 'adj.', 1, 45),
('a0000000-0000-0000-0000-000000000001', 'substitute', '/ˈsʌbstɪtjuːt/', '替代；代替', 'You can substitute honey for sugar in this recipe.', '你可以在这个食谱中用蜂蜜代替糖。', 'v./n.', 1, 46),
('a0000000-0000-0000-0000-000000000001', 'sufficient', '/səˈfɪʃənt/', '足够的；充分的', 'We have sufficient evidence to proceed.', '我们有足够的证据继续推进。', 'adj.', 1, 47),
('a0000000-0000-0000-0000-000000000001', 'tendency', '/ˈtendənsi/', '趋势；倾向', 'There is a tendency toward remote work.', '远程办公是一种趋势。', 'n.', 1, 48),
('a0000000-0000-0000-0000-000000000001', 'ultimate', '/ˈʌltɪmət/', '最终的；根本的', 'The ultimate goal is world peace.', '最终目标是世界和平。', 'adj.', 1, 49),
('a0000000-0000-0000-0000-000000000001', 'voluntary', '/ˈvɒləntəri/', '自愿的；志愿的', 'Participation is completely voluntary.', '参与完全是自愿的。', 'adj.', 1, 50);